package main

import "fmt"

var (
	version   = "dev"
	commit    = "unknown"
	buildDate = "unknown"
)

func displayVersion() string {
	if version == "" {
		return "dev"
	}
	return version
}

func buildInfo() string {
	return fmt.Sprintf("Version: %s  Commit: %s  Built: %s", displayVersion(), commit, buildDate)
}
package main

import "testing"

func TestDisplayVersionFallsBackToDev(t *testing.T) {
	original := version
	t.Cleanup(func() {
		version = original
	})

	version = ""

	if got := displayVersion(); got != "dev" {
		t.Fatalf("displayVersion() = %q, want %q", got, "dev")
	}
}

func TestBuildInfoIncludesVersionMetadata(t *testing.T) {
	originalVersion := version
	originalCommit := commit
	originalBuildDate := buildDate
	t.Cleanup(func() {
		version = originalVersion
		commit = originalCommit
		buildDate = originalBuildDate
	})

	version = "1.2.3"
	commit = "abc123"
	buildDate = "2026-05-23T00:00:00Z"

	got := buildInfo()
	want := "Version: 1.2.3  Commit: abc123  Built: 2026-05-23T00:00:00Z"
	if got != want {
		t.Fatalf("buildInfo() = %q, want %q", got, want)
	}
}
